class Solution {
    public int canCompleteCircuit(int[] gas, int[] cost) {
        int total = 0;
        int tank = 0;
        int start = 0;

        for (int i = 0; i < gas.length; i++) {
            int gain = gas[i] - cost[i];
            total += gain;
            tank += gain;
            if (tank < 0) {
                start = i + 1;
                tank = 0;
            }
        }

        return total < 0 ? -1 : start;
    }
}

class Solution {
    public int canCompleteCircuit(int[] gas, int[] cost) {
        int prefix = 0;
        int minPrefix = 0;
        int start = 0;

        for (int i = 0; i < gas.length; i++) {
            prefix += gas[i] - cost[i];
            if (prefix < minPrefix) {
                minPrefix = prefix;
                start = i + 1;
            }
        }

        return prefix < 0 ? -1 : start % gas.length;
    }
}

class Solution {
    public int canCompleteCircuit(int[] gas, int[] cost) {
        int n = gas.length;
        int start = 0;

        while (start < n) {
            int tank = 0;
            int steps = 0;
            while (steps < n) {
                int station = (start + steps) % n;
                tank += gas[station] - cost[station];
                if (tank < 0) {
                    break;
                }
                steps++;
            }
            if (steps == n) {
                return start;
            }
            start += steps + 1;
        }

        return -1;
    }
}

class Solution {
    public int canCompleteCircuit(int[] gas, int[] cost) {
        int n = gas.length;
        long[] prefix = new long[2 * n + 1];
        for (int i = 0; i < 2 * n; i++) {
            prefix[i + 1] = prefix[i] + gas[i % n] - cost[i % n];
        }
        if (prefix[n] < 0) {
            return -1;
        }

        java.util.Deque<Integer> deque = new java.util.ArrayDeque<>();
        for (int i = 1; i <= 2 * n; i++) {
            while (!deque.isEmpty() && prefix[deque.peekLast()] >= prefix[i]) {
                deque.pollLast();
            }
            deque.offerLast(i);

            int start = i - n;
            if (start >= 0) {
                while (!deque.isEmpty() && deque.peekFirst() <= start) {
                    deque.pollFirst();
                }
                if (start < n && !deque.isEmpty() && prefix[deque.peekFirst()] - prefix[start] >= 0) {
                    return start;
                }
            }
        }

        return -1;
    }
}

class Solution {
    public int canCompleteCircuit(int[] gas, int[] cost) {
        int n = gas.length;
        long[] prefix = new long[2 * n + 1];
        for (int i = 0; i < 2 * n; i++) {
            prefix[i + 1] = prefix[i] + gas[i % n] - cost[i % n];
        }
        if (prefix[n] < 0) {
            return -1;
        }

        RangeMinTree tree = new RangeMinTree(prefix);
        for (int start = 0; start < n; start++) {
            long minBalance = tree.query(start + 1, start + n);
            if (minBalance - prefix[start] >= 0) {
                return start;
            }
        }
        return -1;
    }

    private static class RangeMinTree {
        private final int size;
        private final long[] tree;

        RangeMinTree(long[] values) {
            int capacity = 1;
            while (capacity < values.length) {
                capacity <<= 1;
            }
            size = capacity;
            tree = new long[size * 2];
            java.util.Arrays.fill(tree, Long.MAX_VALUE / 4);
            for (int i = 0; i < values.length; i++) {
                tree[size + i] = values[i];
            }
            for (int i = size - 1; i > 0; i--) {
                tree[i] = Math.min(tree[i * 2], tree[i * 2 + 1]);
            }
        }

        long query(int left, int right) {
            left += size;
            right += size;
            long answer = Long.MAX_VALUE / 4;
            while (left <= right) {
                if ((left & 1) == 1) {
                    answer = Math.min(answer, tree[left++]);
                }
                if ((right & 1) == 0) {
                    answer = Math.min(answer, tree[right--]);
                }
                left >>= 1;
                right >>= 1;
            }
            return answer;
        }
    }
}
